package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.IntrospectionAllowedVO;

class IntrospectionAllowedValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of introspection allowed of oauth client")
  void test_introspection_allowed_value_holder_assign_plain_value() {
    Object holder = new Object();
    IntrospectionAllowedValueHolder<Object> value = new IntrospectionAllowedValueHolder<>(holder);
    Assertions.assertSame(holder, value.introspectionAllowed(true),
        "Setters must return the holder");
    Assertions.assertTrue(value.getIntrospectionAllowedValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getIntrospectionAllowed().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of introspection allowed of oauth client")
  void test_introspection_allowed_value_holder_assign_value_object() {
    Object holder = new Object();
    IntrospectionAllowedValueHolder<Object> value = new IntrospectionAllowedValueHolder<>(holder);
    IntrospectionAllowedVO vo = IntrospectionAllowedVO.from(true);
    Assertions.assertFalse(value.getIntrospectionAllowedValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.introspectionAllowed(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getIntrospectionAllowedValue().orElseThrow());
    Assertions.assertSame(holder, value.introspectionAllowed(Optional.empty()));
    Assertions.assertFalse(value.getIntrospectionAllowedValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.introspectionAllowed(Optional.of(vo)));
    Assertions.assertSame(vo, value.getIntrospectionAllowedValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of introspection allowed of oauth client against the original")
  void test_introspection_allowed_value_holder_read() {
    Object holder = new Object();
    IntrospectionAllowedValueHolder<Object> value = new IntrospectionAllowedValueHolder<>(holder);
    IntrospectionAllowedVO vo = IntrospectionAllowedVO.from(true);
    IntrospectionAllowedVO other = IntrospectionAllowedVO.from(true);
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getIntrospectionAllowedValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readIntrospectionAllowed(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readIntrospectionAllowed(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.introspectionAllowed(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readIntrospectionAllowed(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readIntrospectionAllowed(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of introspection allowed of oauth client")
  void test_introspection_allowed_value_holder_unset() {
    Object holder = new Object();
    IntrospectionAllowedValueHolder<Object> value = new IntrospectionAllowedValueHolder<>(holder);
    IntrospectionAllowedVO vo = IntrospectionAllowedVO.from(true);
    value.introspectionAllowed(vo);
    Assertions.assertSame(holder,
        value.unsetIntrospectionAllowedIfMatches("introspectionAllowed_other"));
    Assertions.assertTrue(value.getIntrospectionAllowedValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetIntrospectionAllowedIfMatches("introspectionAllowed"));
    Assertions.assertFalse(value.getIntrospectionAllowedValue().isPresent(),
        "The field name must clear the value");
    value.introspectionAllowed(vo);
    Assertions.assertSame(holder, value.unsetIntrospectionAllowed());
    Assertions.assertFalse(value.getIntrospectionAllowedValue().isPresent(),
        "Unset must clear the value");
  }
}
